/** The local calendar day chooses a stable pair; neighboring days never share a word. */
export function getWordsForDate(dateKey: string): [VocabularyWord, VocabularyWord] {
  const [year, month, day] = dateKey.split("-").map(Number);
  if (year === undefined || month === undefined || day === undefined) {
    throw new Error("The date key is invalid.");
  }
  const dayNumber = Math.floor(Date.UTC(year, month - 1, day) / 86_400_000);
  const firstIndex = ((dayNumber * 2) % vocabulary.length + vocabulary.length) % vocabulary.length;
  const secondIndex = (firstIndex + 1) % vocabulary.length;
  const first = vocabulary[firstIndex];
  const second = vocabulary[secondIndex];
  if (!first || !second || first.id === second.id) throw new Error("The daily word pair is unavailable.");
  return [first, second];
}

export function getLocalDateKey(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function getScheduleAccess(date: Date, previewMode: boolean) {
  const minuteOfDay = date.getHours() * 60 + date.getMinutes();
  return {
    morning: previewMode || minuteOfDay >= 6 * 60,
    evening: previewMode || minuteOfDay >= 17 * 60,
    quiz: previewMode || minuteOfDay >= 20 * 60 + 30,
  };
}

export type QuizQuestion = {
  wordId: string;
  word: string;
  type: "Synonym" | "Antonym" | "Meaning" | "Sentence usage";
  prompt: string;
  choices: string[];
  answer: string;
  explanation: string;
};

export function buildDailyQuiz(words: [VocabularyWord, VocabularyWord]): QuizQuestion[] {
  const questionTypes: QuizQuestion["type"][] = ["Synonym", "Antonym", "Meaning", "Sentence usage"];
  return words.flatMap((word, wordIndex) => questionTypes.map((type, typeIndex) => {
    const otherWord = words[1 - wordIndex];
    if (!otherWord) throw new Error("The daily quiz word pair is incomplete.");
    const start = (wordIndex * 17 + typeIndex * 11 + 3) % vocabulary.length;
    const distractor = vocabulary[(start + (start === 0 ? 1 : 0)) % vocabulary.length];
    const secondDistractor = vocabulary[(start + 7) % vocabulary.length];
    let answer = "";
    let choices: string[] = [];
    let prompt = "";
    let explanation = "";

    if (type === "Synonym") {
      answer = word.synonyms[0];
      choices = [answer, word.antonyms[0], otherWord.word, distractor?.word ?? "other"];
      prompt = `Which word is a synonym for “${word.word}”?`;
      explanation = `“${answer}” is a synonym because it has a similar meaning to ${word.word}.`;
    } else if (type === "Antonym") {
      answer = word.antonyms[0];
      choices = [answer, word.synonyms[0], otherWord.word, secondDistractor?.word ?? "other"];
      prompt = `Which word is an antonym (opposite) of “${word.word}”?`;
      explanation = `“${answer}” is an antonym: it expresses an opposite idea to ${word.word}.`;
    } else if (type === "Meaning") {
      answer = word.meaning;
      choices = [answer, otherWord.meaning, distractor?.meaning ?? "A different idea.", secondDistractor?.meaning ?? "Another idea."];
      prompt = `What is the correct meaning of “${word.word}”?`;
      explanation = `“${word.word}” means ${word.meaning.charAt(0).toLowerCase()}${word.meaning.slice(1)}`;
    } else {
      answer = word.examples[0];
      choices = [answer, otherWord.examples[0], distractor?.examples[0] ?? "A different example.", secondDistractor?.examples[0] ?? "Another example."];
      prompt = `Which sentence uses “${word.word}” correctly?`;
      explanation = `“${answer}” uses ${word.word} naturally and correctly.`;
    }

    const filler = type === "Meaning"
      ? vocabulary.map((item) => item.meaning)
      : type === "Sentence usage"
        ? vocabulary.map((item) => item.examples[0])
        : vocabulary.map((item) => item.word);
    choices = [...new Set([answer, ...choices.filter((choice) => choice !== answer), ...filler.filter((choice) => choice !== answer)])].slice(0, 4);
    const shift = (wordIndex * 3 + typeIndex) % choices.length;
    choices = [...choices.slice(shift), ...choices.slice(0, shift)];
    return { wordId: word.id, word: word.word, type, prompt, choices, answer, explanation };
  }));
}
